package lk.gov.health.govcare.ai;

import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.databind.node.ObjectNode;
import org.junit.jupiter.api.Test;
import java.nio.file.*;
import java.time.Instant;
import java.util.*;
import static org.junit.jupiter.api.Assertions.*;

/** Optional operational browser fixtures generated by the actual patient-data assembler, with no invented predictions. */
class RenalReadinessUiFixtureTest {
    @Test void generateRealReadinessResponsesForUiVerification() throws Exception {
        var mapper=new ObjectMapper().findAndRegisterModules();ObjectNode scenarios=mapper.createObjectNode();
        var empty=RenalReadinessTest.data(List.of());
        var first=RenalReadinessTest.row(31,false,Map.of("hb",10.8,"creatinine_pre",195.0));
        var last=RenalReadinessTest.row(1,false,Map.of("hb",10.2,"creatinine_pre",211.0,"potassium_pre",4.8));
        List<List<SriLankanRenalIntelligenceService.ObservationView>> rows=List.of(List.of(),List.of(first),List.of(first,last),
                List.of(RenalReadinessTest.row(1,true,RenalReadinessTest.labs())),
                List.of(RenalReadinessTest.row(31,true,RenalReadinessTest.labs()),RenalReadinessTest.row(1,true,RenalReadinessTest.labs())));
        String[] names={"empty","one","partial","paired","ready"};
        for(int i=0;i<names.length;i++){
            var context=new SriLankanRenalIntelligenceService.Overview(empty.patientId(),empty.hospitalId(),empty.currentRenalStatus(),rows.get(i),List.of(),null,true,false);
            var out=RenalClinicalModules.assemble(context,RenalReadinessTest.registry(),RenalReadinessTest.NOW);decorate(out);
            scenarios.set(names[i],out);
        }
        var unavailable=RenalClinicalModules.assemble(empty,List.of(),RenalReadinessTest.NOW);decorate(unavailable);scenarios.set("notInstalled",unavailable);
        var clinicalStatus=new SriLankanRenalIntelligenceService.RenalStatus("G5D","Verified maintenance dialysis","Operational clinical verification",null,null,null,"MAINTENANCE_HD",RenalReadinessTest.NOW,"Operational source verification; not a clinical subject",UUID.randomUUID());
        var clinical=new SriLankanRenalIntelligenceService.Overview(empty.patientId(),empty.hospitalId(),clinicalStatus,List.of(),List.of(),null,true,false);
        var verified=RenalClinicalModules.assemble(clinical,RenalReadinessTest.registry(),RenalReadinessTest.NOW);decorate(verified);scenarios.set("verifiedContext",verified);
        var previous=rows.getLast().getFirst();var current=rows.getLast().getLast();
        var error=mapper.createObjectNode().put("forecast_origin_date",current.observedAt().toString()).put("method","RESEARCH_MODEL");error.putObject("explanation").putArray("limitations").add("Operational service outage fixture");
        var p=new SriLankanRenalIntelligenceService.PredictionView(UUID.randomUUID(),"hyperkalemia","NOT_AVAILABLE",error,RenalReadinessTest.NOW,"AWAITING_REVIEW",0);
        var failed=new SriLankanRenalIntelligenceService.Overview(empty.patientId(),empty.hospitalId(),empty.currentRenalStatus(),List.of(previous,current),List.of(p),null,true,false);
        var failedOut=RenalClinicalModules.assemble(failed,RenalReadinessTest.registry(),RenalReadinessTest.NOW);decorate(failedOut);scenarios.set("error",failedOut);
        for(var scenario:scenarios)for(String key:RenalClinicalModules.ORDER)assertTrue(scenario.path(key).path("researchRiskScore").isNull());
        String directory=System.getProperty("govcare.renal.readiness.qa.output");
        if(directory!=null){Path target=Path.of(directory);Files.createDirectories(target);Files.writeString(target.resolve("readiness-ui-fixtures-v48.json"),scenarios.toPrettyString());}
    }
    private void decorate(ObjectNode out){out.put("snapshotId",UUID.randomUUID().toString());for(String key:RenalClinicalModules.ORDER){var module=(ObjectNode)out.get(key);module.put("moduleReviewVersion",0).put("moduleReviewState","AWAITING_REVIEW");module.putNull("clinicianReview");}}
}
